def countQueensBlocked(n, blocked):
    full = (1 << n) - 1
    forbidden = [0] * n
    for r, c in blocked:
        forbidden[r] |= 1 << c

    def go(r, used, down, up):
        if r == n:
            return 1
        free = full & ~(used | down | up | forbidden[r])
        total = 0
        while free:
            bit = free & -free
            free ^= bit
            total += go(r + 1, used | bit, ((down | bit) << 1) & full, (up | bit) >> 1)
        return total

    return go(0, 0, 0, 0)
